package com.xianshuyuan.scm.order.controller;import com.xianshuyuan.scm.common.api.ApiResponse;import com.xianshuyuan.scm.order.dto.OrderRefundCompleteRequest;import com.xianshuyuan.scm.order.service.*;import com.xianshuyuan.scm.order.vo.OrderRefundResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/order-refunds")public class OrderRefundController{private final AfterSalesApplicationService app;private final AfterSalesQueryService query;public OrderRefundController(AfterSalesApplicationService a,AfterSalesQueryService q){app=a;query=q;}@GetMapping("/{id}")public ApiResponse<OrderRefundResponse> get(@PathVariable long id){return ApiResponse.success(query.getRefund(id));}@PostMapping("/{id}/complete")public ApiResponse<Void> complete(@RequestHeader("Idempotency-Key")String key,@PathVariable long id,@Valid @RequestBody OrderRefundCompleteRequest r){app.completeRefund(key,id,r);return ApiResponse.success(null);}}
